CREATE TABLE asset_locations (asset_id TEXT NOT NULL,project_id TEXT NOT NULL,owner_id TEXT NOT NULL,agent_id TEXT NOT NULL,last_seen_at TEXT NOT NULL,PRIMARY KEY(asset_id,agent_id),FOREIGN KEY(asset_id,project_id) REFERENCES assets(id,project_id) ON DELETE RESTRICT,FOREIGN KEY(project_id,owner_id) REFERENCES projects(id,owner_id) ON DELETE RESTRICT,FOREIGN KEY(agent_id,owner_id) REFERENCES local_agents(id,owner_id) ON DELETE RESTRICT);
